#!/usr/bin/env node
/**
 * 政府网站新闻抓取脚本 (Node.js版本)
 * 使用 Playwright 抓取 40 个政府网站的新闻和政策
 */

const fs = require('fs');
const path = require('path');

// 动态导入 playwright (ESM 方式)
async function getPlaywright() {
  const { chromium } = await import('playwright');
  return { chromium };
}

// 配置
const CONFIG_DIR = path.join(process.env.HOME, '.openclaw/workspace/projects/daily-news-crawler/config');
const OUTPUT_DIR = path.join(process.env.HOME, 'DailyReports');
const DAYS_BACK = 7; // 抓取最近 7 天的内容

class NewsCrawler {
  constructor() {
    this.results = [];
    this.errors = [];
  }

  parseDate(dateText) {
    // 解析各种日期格式
    const patterns = [
      { regex: /(\d{4})-(\d{2})-(\d{2})/, format: 'ymd' },
      { regex: /(\d{4})\/(\d{2})\/(\d{2})/, format: 'ymd' },
      { regex: /(\d{4})年(\d{2})月(\d{2})日/, format: 'ymd' },
      { regex: /(\d{2})-(\d{2})/, format: 'md' },
    ];

    for (const { regex, format } of patterns) {
      const match = dateText.match(regex);
      if (match) {
        if (format === 'ymd') {
          return `${match[1]}-${match[2]}-${match[3]}`;
        } else if (format === 'md') {
          const year = new Date().getFullYear();
          return `${year}-${match[1]}-${match[2]}`;
        }
      }
    }
    return '';
  }

  async function crawlSite(page, siteConfig) {
    const url = siteConfig.url;
    const name = siteConfig.name;
    const selectors = siteConfig.selector || {};

    console.log(`[INFO] 正在抓取: ${name} (${url})`);

    try {
      // 访问页面
      await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
      await page.waitForLoadState('domcontentloaded');

      // 等待内容加载
      const listSelector = selectors.list || '.news-list li, .list-item';
      try {
        await page.waitForSelector(listSelector, { timeout: 10000 });
      } catch (e) {
        console.log(`[WARN] ${name}: 未找到列表元素，尝试备用选择器`);
        // 尝试其他常见选择器
        const backups = ['.news-item', '.list-news li', '.content-list li', 'tr'];
        for (const backup of backups) {
          try {
            await page.waitForSelector(backup, { timeout: 5000 });
            listSelector = backup;
            console.log(`[INFO] ${name}: 使用备用选择器 ${backup}`);
            break;
          } catch (e2) {
            continue;
          }
        }
      }

      // 提取新闻列表
      const items = await page.$$(listSelector);
      console.log(`[INFO] ${name}: 找到 ${items.length} 个条目`);

      const newsList = [];
      for (let i = 0; i < Math.min(items.length, 20); i++) {
        const item = items[i];
        try {
          // 提取标题
          let titleElem = await item.$(selectors.title || '.title, a, .news-title');
          if (!titleElem) {
            titleElem = item;
          }

          let title = await titleElem.textContent();
          title = title ? title.trim() : '';

          if (!title || title.length < 5) {
            continue;
          }

          // 提取链接
          let link = url;
          const linkElem = await item.$('a');
          if (linkElem) {
            const href = await linkElem.getAttribute('href');
            if (href) {
              // 处理相对 URL
              if (href.startsWith('http')) {
                link = href;
              } else {
                const baseUrl = new URL(url);
                link = new URL(href, baseUrl).href;
              }
            }
          }

          // 提取日期
          let date = '';
          const dateElem = await item.$(selectors.date || '.date, .time, .news-date');
          if (dateElem) {
            const dateText = await dateElem.textContent();
            date = this.parseDate(dateText ? dateText.trim() : '');
          }

          if (!date) {
            // 如果没有日期，使用当前日期
            date = new Date().toISOString().split('T')[0];
          }

          // 检查是否在指定时间范围内
          try {
            const itemDate = new Date(date);
            const cutoffDate = new Date();
            cutoffDate.setDate(cutoffDate.getDate() - DAYS_BACK);
            if (itemDate < cutoffDate) {
              continue; // 跳过旧内容
            }
          } catch (e) {
            // 日期解析失败，保留该条目
          }

          // 提取摘要
          let summary = '';
          const summaryElem = await item.$(selectors.summary || '.summary, .content, .news-content');
          if (summaryElem) {
            const summaryText = await summaryElem.textContent();
            summary = summaryText ? summaryText.trim() : '';
            if (summary.length > 100) {
              summary = summary.substring(0, 100) + '...';
            }
          }

          if (!summary) {
            summary = title.length > 50 ? title.substring(0, 50) + '...' : title;
          }

          const newsItem = {
            site_name: name,
            site_url: url,
            category: siteConfig.category || '其他',
            title: title,
            url: link,
            date: date,
            summary: summary,
            crawled_at: new Date().toISOString()
          };

          newsList.push(newsItem);

        } catch (e) {
          console.log(`[WARN] ${name}: 解析条目失败: ${e.message}`);
          continue;
        }
      }

      console.log(`[INFO] ${name}: 成功提取 ${newsList.length} 条新闻`);
      return newsList;

    } catch (e) {
      const errorMsg = `[ERROR] ${name}: 抓取失败 - ${e.message}`;
      console.log(errorMsg);
      this.errors.push({
        site_name: name,
        site_url: url,
        error: e.message,
        timestamp: new Date().toISOString()
      });
      return [];
    }
  }

  async run() {
    console.log('='.repeat(60));
    console.log(`[INFO] 开始抓取任务 - ${new Date().toLocaleString('zh-CN')}`);
    console.log('='.repeat(60));

    // 读取配置
    const configFile = path.join(CONFIG_DIR, 'urls.json');
    if (!fs.existsSync(configFile)) {
      console.log(`[ERROR] 配置文件不存在: ${configFile}`);
      return [];
    }

    const config = JSON.parse(fs.readFileSync(configFile, 'utf-8'));
    const sites = config.sources || [];
    console.log(`[INFO] 共 ${sites.length} 个网站需要抓取`);

    // 使用 Playwright 抓取
    const { chromium } = await getPlaywright();
    const browser = await chromium.launch({ headless: true });

    // 串行抓取（避免并发过大）
    for (let i = 0; i < sites.length; i++) {
      const site = sites[i];
      console.log(`\n[${i + 1}/${sites.length}] `);

      const page = await browser.newPage();

      try {
        const news = await this.crawlSite(page, site);
        this.results = this.results.concat(news);
      } catch (e) {
        console.log(`[ERROR] 未捕获的异常: ${e.message}`);
      }

      await page.close();
    }

    await browser.close();

    // 输出统计
    console.log('\n' + '='.repeat(60));
    console.log(`[INFO] 抓取完成 - ${new Date().toLocaleString('zh-CN')}`);
    console.log(`[INFO] 成功抓取: ${this.results.length} 条新闻`);
    console.log(`[INFO] 失败站点: ${this.errors.length} 个`);
    console.log('='.repeat(60));

    return this.results;
  }
}

async function main() {
  const crawler = new NewsCrawler();
  const results = await crawler.run();

  // 输出结果到文件
  const outputDir = path.join(process.env.HOME, 'DailyReports');
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const outputFile = path.join(outputDir, `crawl_result_${new Date().toISOString().slice(0, 10).replace(/-/g, '')}_${Date.now()}.json`);

  fs.writeFileSync(outputFile, JSON.stringify({
    results: results,
    errors: crawler.errors,
    timestamp: new Date().toISOString()
  }, null, 2), 'utf-8');

  console.log(`[INFO] 结果已保存到: ${outputFile}`);
}

main().catch(e => {
  console.error('[ERROR] 程序异常:', e);
  process.exit(1);
});

